import queue
import random
import threading
import time
from collections import Counter

import pytest

from bounded_queue import BoundedQueue


# ---------------------------------------------------------------- helpers

class Watchdog:
    """Fail the test if the body doesn't finish within `limit` seconds."""

    def __init__(self, limit=10.0):
        self.limit = limit
        self.done = threading.Event()
        self.error = None

    def __enter__(self):
        def bark():
            if not self.done.wait(self.limit):
                self.error = RuntimeError(
                    f"watchdog fired: stress run exceeded {self.limit}s"
                )
                # Unblock any stuck threads so the test process can exit.
                import faulthandler, sys
                faulthandler.dump_traceback()

        self.t = threading.Thread(target=bark, daemon=True)
        self.t.start()
        return self

    def __exit__(self, *exc):
        self.done.set()
        self.t.join()
        if self.error:
            raise self.error
        return False


# ---------------------------------------------------------------- tests

def test_fifo_under_concurrency():
    """4 producers x 4 consumers moving 10k items: multiset match + per-producer order."""
    n_producers, n_consumers = 4, 4
    per_producer = 2_500
    total = n_producers * per_producer
    q = BoundedQueue(capacity=64)

    produced = {p: [] for p in range(n_producers)}
    consumed = []
    consumed_lock = threading.Lock()
    start = threading.Barrier(n_producers + n_consumers)

    def producer(pid):
        rng = random.Random(1000 + pid)
        start.wait()
        for i in range(per_producer):
            q.put((pid, i))
            produced[pid].append(i)
            if rng.random() < 0.1:
                time.sleep(0)

    def consumer(_cid):
        got_local = []
        start.wait()
        for _ in range(total // n_consumers):
            got_local.append(q.get(timeout=30))
        with consumed_lock:
            consumed.extend(got_local)

    with Watchdog(10):
        threads = [threading.Thread(target=producer, args=(p,)) for p in range(n_producers)]
        threads += [threading.Thread(target=consumer, args=(c,)) for c in range(n_consumers)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=15)
        assert not any(t.is_alive() for t in threads), "thread stuck"

    # Multiset equality: nothing lost, nothing duplicated.
    assert Counter(consumed) == Counter(
        (p, i) for p in range(n_producers) for i in range(per_producer)
    )

    # Per-producer subsequence order in the consumption stream.
    positions = {p: [] for p in range(n_producers)}
    for idx, (pid, seq) in enumerate(consumed):
        positions[pid].append(seq)
    for pid in range(n_producers):
        assert positions[pid] == sorted(positions[pid]), (
            f"producer {pid} items observed out of order"
        )

    # And producers actually emitted each sequence in order (sanity on harness).
    for pid in range(n_producers):
        assert produced[pid] == list(range(per_producer))


def test_put_on_full_times_out_approximately():
    q = BoundedQueue(capacity=1)
    q.put("occupant")
    start = time.monotonic()
    with pytest.raises(queue.Full):
        q.put("nope", timeout=0.1)
    elapsed = time.monotonic() - start
    assert 0.05 < elapsed < 0.5, f"put timed out after {elapsed:.3f}s"


def test_get_on_empty_times_out():
    q = BoundedQueue(capacity=4)
    start = time.monotonic()
    with pytest.raises(queue.Empty):
        q.get(timeout=0.1)
    elapsed = time.monotonic() - start
    assert 0.05 < elapsed < 0.5, f"get timed out after {elapsed:.3f}s"


def test_stress_no_lost_wakeups():
    """8 threads hammering the queue; must complete well within watchdog."""
    q = BoundedQueue(capacity=random.choice([1, 3, 8]))
    rounds = 400
    errors = []

    def worker(wid):
        try:
            rng = random.Random(wid)
            for i in range(rounds):
                if wid % 2 == 0:
                    try:
                        q.put((wid, i), timeout=5)
                    except queue.Full:
                        # Drain one item ourselves and retry - exercises both paths.
                        q.get(timeout=5)
                        q.put((wid, i), timeout=5)
                    try:
                        q.get(timeout=5)
                    except queue.Empty:
                        pass
                else:
                    try:
                        q.get(timeout=5)
                    except queue.Empty:
                        pass
                    try:
                        q.put((wid, i), timeout=5)
                    except queue.Full:
                        pass
                    if rng.random() < 0.05:
                        time.sleep(0)
        except Exception as e:  # noqa: BLE001
            errors.append(e)

    with Watchdog(10):
        threads = [threading.Thread(target=worker, args=(i,)) for i in range(8)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=12)
        assert not any(t.is_alive() for t in threads), "stress thread hung"
    assert not errors, f"worker errors: {errors}"


def test_basic_fifo_single_threaded():
    q = BoundedQueue(capacity=3)
    for i in range(3):
        q.put(i)
    assert [q.get() for _ in range(3)] == [0, 1, 2]

