import threading, random
from collections import Counter
from bounded_queue import BoundedQueue

for trial in range(3):
    n_p, n_c, per = 4, 4, 2500
    q = BoundedQueue(64)
    consumed, lock = [], threading.Lock()
    start = threading.Barrier(n_p + n_c)
    def prod(pid):
        start.wait()
        for i in range(per): q.put((pid, i))
    def cons(cid):
        local = []
        start.wait()
        for _ in range(n_p*per//n_c): local.append(q.get(timeout=30))
        with lock: consumed.extend(local)
    ts = [threading.Thread(target=prod, args=(p,)) for p in range(n_p)] + \
         [threading.Thread(target=cons, args=(c,)) for c in range(n_c)]
    for t in ts: t.start()
    for t in ts: t.join()
    assert Counter(consumed) == Counter((p,i) for p in range(n_p) for i in range(per))
    pos = {p: [] for p in range(n_p)}
    for pid, seq in consumed: pos[pid].append(seq)
    for pid in range(n_p):
        s = pos[pid]
        bad = [(i, s[i], s[i+1]) for i in range(len(s)-1) if s[i] > s[i+1]]
        if bad:
            print(f"trial {trial} producer {pid}: {len(bad)} inversions, first few: {bad[:5]}")
            print("head:", s[:10])
            break
    else:
        print(f"trial {trial}: OK")
